def compute_tax_sla_schedule(quote: dict) -> dict:
    net_cents = int(quote['net_cents'])
    tax_cents = (net_cents * 1000) // 10000
    return {
        'tax_cents': tax_cents,
        'gross_collected_cents': net_cents + tax_cents,
        'expansion_denied': True,
        'shed_incident_indices': [],
        'start_ticks': [0, 0, 2],
    }

